/**
 * Credits page body (lazy chunk): purpose, nonprofit, disclaimer, attribution records from
 * `manifest.attributions`, the full ATTRIBUTION.md (generated by the pipeline, bundled as text) and the licence
 * files the build ships under licenses/ (vite.config.ts).
 */
import { useTranslation } from 'react-i18next';
import attributionText from '../../../ATTRIBUTION.md?raw';
import { APP_NAME, APP_REPO_URL } from '@/config';
import { useAtlasStore } from '@/state';
import { cx, mutedText } from '../components/classes';
import { Icon } from '../components/Icon';
import { Badge, SectionTitle } from '../components/ui';
import { licenseLabel } from '../lib/licenses';

export default function CreditsContent() {
  const { t } = useTranslation();
  const manifest = useAtlasStore((s) => s.manifest);
  const attributions = Object.entries(manifest?.attributions ?? {});
  const repoUrl: string = APP_REPO_URL;
  const file = (name: string) => `${import.meta.env.BASE_URL}licenses/${name}`;
  const link = 'text-teal-800 underline underline-offset-2 hover:no-underline dark:text-teal-300';
  return (
    <div className="flex flex-col gap-5 text-sm leading-relaxed">
      <section className="flex flex-col gap-1.5">
        <h3 className="text-lg font-bold">{APP_NAME}</h3>
        <p>{t('credits.purpose')}</p>
      </section>

      <section
        className="flex gap-3 rounded-xl border border-amber-300 bg-amber-50 p-3 text-amber-950 dark:border-amber-400/40 dark:bg-amber-400/10 dark:text-amber-100"
        aria-labelledby="disclaimer-title"
      >
        <Icon name="alert" className="mt-0.5 size-5" />
        <div>
          <h3 id="disclaimer-title" className="font-semibold">
            {t('credits.disclaimerTitle')}
          </h3>
          <p>{t('credits.disclaimer')}</p>
        </div>
      </section>

      <section className="flex flex-col gap-2" aria-labelledby="attr-title">
        <SectionTitle id="attr-title">{t('credits.attributionTitle')}</SectionTitle>
        <p className={mutedText}>{t('credits.attributionIntro')}</p>
        {manifest ? (
          <p>
            <a className={link} href={manifest.source.url} target="_blank" rel="noopener noreferrer">
              {manifest.source.name}
            </a>{' '}
            · {manifest.source.license}
          </p>
        ) : null}
        <ul className="flex flex-col gap-2">
          {attributions.map(([id, a]) => (
            <li
              key={id}
              className="rounded-lg border border-zinc-200 p-2.5 dark:border-zinc-700"
              data-attribution={id}
            >
              <p>{a.text}</p>
              <p className={cx('mt-1 flex flex-wrap items-center gap-2 text-xs', mutedText)}>
                {a.license && a.licenseUrl ? (
                  <a className={link} href={a.licenseUrl} target="_blank" rel="noopener noreferrer">
                    {licenseLabel(a.license)}
                  </a>
                ) : (
                  <span>{t('credits.noLicense')}</span>
                )}
                {a.url ? (
                  <a className={link} href={a.url} target="_blank" rel="noopener noreferrer">
                    {a.url.replace(/^https?:\/\//, '')}
                  </a>
                ) : null}
                {a.nonCommercial ? <Badge tone="warn">{t('credits.nonCommercial')}</Badge> : null}
              </p>
            </li>
          ))}
        </ul>
        <details
          className="rounded-lg border border-zinc-200 p-2.5 dark:border-zinc-700"
          data-testid="full-attribution"
        >
          <summary className="cursor-pointer font-medium">{t('credits.fullAttribution')}</summary>
          <pre className="mt-2 max-h-96 overflow-auto font-[inherit] text-xs leading-relaxed break-words whitespace-pre-wrap">
            {attributionText}
          </pre>
        </details>
        <p className={cx('flex flex-wrap gap-x-3 gap-y-1 text-xs', mutedText)}>
          <a className={link} href={file('ATTRIBUTION.txt')} target="_blank" rel="noopener">
            ATTRIBUTION
          </a>
          <a className={link} href={file('LICENSE.txt')} target="_blank" rel="noopener">
            {t('credits.codeLicenseFile')}
          </a>
          <a className={link} href={file('assets-LICENSE.txt')} target="_blank" rel="noopener">
            {t('credits.assetLicenseFile')}
          </a>
          {repoUrl ? (
            <a className={link} href={repoUrl} target="_blank" rel="noopener noreferrer">
              {t('credits.repository')}
            </a>
          ) : null}
        </p>
      </section>

      <section className="flex flex-col gap-2" aria-labelledby="lic-title">
        <SectionTitle id="lic-title">{t('credits.licensesTitle')}</SectionTitle>
        <ul className="ml-4 list-disc space-y-1">
          <li>{t('credits.codeLicense')}</li>
          <li>{t('credits.assetLicense')}</li>
          <li>{t('credits.definitionLicense')}</li>
          <li>{t('credits.taLicense')}</li>
        </ul>
      </section>

      <section className="flex flex-col gap-1.5" aria-labelledby="privacy-title">
        <SectionTitle id="privacy-title">{t('credits.privacyTitle')}</SectionTitle>
        <p>{t('credits.privacy')}</p>
      </section>
    </div>
  );
}
